#!/usr/bin/env bash
# Generated by mule-cicd-kit 1.0.0 - do not edit by hand.
# The same steps run in every CI/CD tool, and you can run them locally too.
#
#   bash cicd/mule-cicd.sh build              build the app and run MUnit tests
#   bash cicd/mule-cicd.sh publish            publish the app to Anypoint Exchange
#   bash cicd/mule-cicd.sh deploy <env>       deploy the published version to CloudHub 2.0
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."
source cicd/pipeline.env

STAGE="${1:-}"
TARGET_ENV="${2:-}"
MVN=(mvn -B -ntp -s cicd/settings.xml)

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

require() {
  local name
  for name in "$@"; do
    [ -n "${!name:-}" ] || fail "$name is not set. Add it to your CI/CD secrets (see cicd/README-PIPELINE.md)."
  done
}

project_version() {
  "${MVN[@]}" -q help:evaluate -Dexpression=project.version -DforceStdout
}

# Exchange versions can't be overwritten, so every published build needs its own release version.
apply_version() {
  if [ "$VERSION_STRATEGY" = "build-number" ]; then
    require PIPELINE_BUILD_ID
    local base
    base="$(project_version)"
    base="${base%-SNAPSHOT}"
    echo "Using version ${base}-${PIPELINE_BUILD_ID}"
    "${MVN[@]}" -q versions:set -DnewVersion="${base}-${PIPELINE_BUILD_ID}" -DgenerateBackupPoms=false
  fi
  local version
  version="$(project_version)"
  case "$version" in
    *-SNAPSHOT) fail "Version $version is a SNAPSHOT. Set a release version in pom.xml (e.g. 1.0.0) or use versionStrategy 'build-number'." ;;
  esac
}

case "$STAGE" in
  build)
    if [ "$RUN_MUNIT" = "true" ]; then
      "${MVN[@]}" clean verify
    else
      "${MVN[@]}" clean package -DskipMunitTests
    fi
    ;;

  publish)
    require ANYPOINT_CLIENT_ID ANYPOINT_CLIENT_SECRET
    apply_version
    "${MVN[@]}" clean deploy -DskipMunitTests
    ;;

  deploy)
    [ -n "$TARGET_ENV" ] || fail "Usage: bash cicd/mule-cicd.sh deploy <environment>"
    ENV_FILE="cicd/environments/$TARGET_ENV.env"
    [ -f "$ENV_FILE" ] || fail "No settings for environment '$TARGET_ENV' ($ENV_FILE not found)."
    source "$ENV_FILE"
    require ANYPOINT_CLIENT_ID ANYPOINT_CLIENT_SECRET
    if [ "$USES_SECURE_PROPERTIES" = "true" ]; then
      KEY_VAR="MULE_KEY_$(echo "$TARGET_ENV" | tr '[:lower:]' '[:upper:]')"
      require "$KEY_VAR"
      export MULE_SECURE_KEY="${!KEY_VAR}"
    fi
    apply_version
    echo "Deploying $APP_NAME to '$ANYPOINT_ENVIRONMENT' on $CH2_TARGET ($REPLICAS x $VCORES vCores)"
    # maven.deploy.skip: the version is already in Exchange (publish stage); only deploy it.
    "${MVN[@]}" clean deploy -DmuleDeploy -DskipMunitTests -Dmaven.deploy.skip=true \
      -Ddeploy.anypointEnvironment="$ANYPOINT_ENVIRONMENT" \
      -Ddeploy.applicationName="$APP_NAME" \
      -Ddeploy.target="$CH2_TARGET" \
      -Ddeploy.replicas="$REPLICAS" \
      -Ddeploy.vCores="$VCORES" \
      -Ddeploy.muleEnv="$MULE_ENV_VALUE"
    ;;

  *)
    fail "Usage: bash cicd/mule-cicd.sh build | publish | deploy <environment>"
    ;;
esac
